/* Stall Sense: market ledger. Every colour has one job:
   ink = text, green = what to bring / money gained,
   tomato = waste / warnings, kraft = quiet structure. */
:root {
  --paper: #F2ECDF;
  --kraft: #E7DFCD;
  --rule: #CDBFA5;
  --ink: #1E1A15;
  --ink-soft: #5B5246;
  --green: #2F5D34;
  --tomato: #B83A24;
  --mono: "JetBrains Mono", ui-monospace, monospace;
  --serif: "Fraunces", Georgia, serif;
}

/* Strip Streamlit chrome */
#MainMenu, footer, [data-testid="stDecoration"], [data-testid="stToolbar"] { display: none !important; }
[data-testid="stHeader"] { background: transparent; }
.block-container { max-width: 1080px; padding-top: 2.2rem; padding-bottom: 4rem; }

h1, h2, h3 { font-variation-settings: "opsz" 72, "SOFT" 50; letter-spacing: -0.01em; }

/* Masthead */
.masthead { border-bottom: 3px double var(--ink); padding-bottom: 0.9rem; margin-bottom: 0.4rem; }
.masthead .dateline {
  font-family: var(--mono); font-size: 0.72rem; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--ink-soft);
  display: flex; justify-content: space-between; flex-wrap: wrap; gap: 0.5rem;
}
.masthead .wordmark {
  font-family: var(--serif); font-weight: 800; font-size: clamp(2.6rem, 6vw, 4.2rem);
  line-height: 0.95; margin: 0.35rem 0 0.5rem; font-variation-settings: "opsz" 144, "SOFT" 100, "WONK" 1;
}
.masthead .wordmark em { font-weight: 400; color: var(--green); }
.masthead .standfirst { font-size: 1.12rem; max-width: 46ch; color: var(--ink); margin: 0; }

/* Demo data notice: a rubber stamp, not a blue info box */
.stamp {
  display: inline-block; font-family: var(--mono); font-size: 0.72rem; letter-spacing: 0.14em;
  text-transform: uppercase; color: var(--tomato); border: 1.5px solid var(--tomato);
  padding: 0.2rem 0.55rem; transform: rotate(-1.5deg); margin: 0.6rem 0 0.2rem;
}
.stamp-note { font-size: 0.86rem; color: var(--ink-soft); margin-left: 0.6rem; }

/* Tabs: plain section labels on a rule */
.stTabs [data-baseweb="tab-list"] { gap: 2rem; border-bottom: 1px solid var(--ink); }
.stTabs [data-baseweb="tab"] {
  font-family: var(--mono); font-size: 0.8rem; letter-spacing: 0.08em; text-transform: uppercase;
  padding: 0.6rem 0; background: transparent;
}

/* Buttons: ink stamp */
.stButton button, .stDownloadButton button {
  font-family: var(--mono); text-transform: uppercase; letter-spacing: 0.08em; font-size: 0.8rem;
  border: 1.5px solid var(--ink); box-shadow: none;
}
.stButton button[kind="primary"] { background: var(--ink); color: var(--paper); border-color: var(--ink); }
.stButton button[kind="primary"]:hover { background: var(--green); border-color: var(--green); }

.kicker {
  font-family: var(--mono); font-size: 0.72rem; letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--ink-soft); margin: 1.4rem 0 0.2rem;
}
.section-title { font-family: var(--serif); font-size: 1.9rem; font-weight: 700; margin: 0 0 0.6rem;
  font-variation-settings: "opsz" 96, "SOFT" 50; }
.hint { color: var(--ink-soft); font-size: 0.92rem; }

/* The load list: one ledger line per item */
.loadlist { border-top: 2px solid var(--ink); margin-top: 0.8rem; }
.loadlist .head, .loadlist .line {
  display: grid; grid-template-columns: 5.2rem 9rem 1fr; column-gap: 1.2rem; align-items: center;
}
.loadlist .head {
  font-family: var(--mono); font-size: 0.68rem; letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--ink-soft); padding: 0.45rem 0; border-bottom: 1px solid var(--rule);
}
.loadlist .line { padding: 0.85rem 0; border-bottom: 1px solid var(--rule); }
.loadlist .qty { font-family: var(--mono); font-weight: 700; font-size: 2.3rem; line-height: 1; color: var(--green); text-align: right; }
.loadlist .unit { font-family: var(--mono); font-size: 0.72rem; color: var(--ink-soft); text-align: right; }
.loadlist .name { font-family: var(--serif); font-size: 1.35rem; font-weight: 600; text-transform: capitalize; }
.loadlist .why { font-size: 0.86rem; color: var(--ink-soft); margin-top: 0.15rem; }
.loadlist .why b { color: var(--tomato); font-weight: 500; }

/* Range: slow day ... busy day, with the recommendation marked */
.range { position: relative; height: 2.2rem; }
.range .track { position: absolute; top: 0.95rem; left: 0; right: 0; height: 1px; background: var(--rule); }
.range .span { position: absolute; top: 0.7rem; height: 0.5rem; background: var(--kraft); border: 1px solid var(--rule); }
.range .mid { position: absolute; top: 0.55rem; width: 1px; height: 0.8rem; background: var(--ink-soft); }
.range .pick { position: absolute; top: 0.35rem; width: 3px; height: 1.2rem; background: var(--green); }
.range .lab { position: absolute; top: 1.45rem; font-family: var(--mono); font-size: 0.66rem; color: var(--ink-soft); transform: translateX(-50%); white-space: nowrap; }

/* Track record */
.verdict { font-family: var(--serif); font-size: 1.55rem; line-height: 1.3; max-width: 40ch; margin: 0.4rem 0 1.2rem;
  font-variation-settings: "opsz" 72, "SOFT" 50; }
.verdict .g { color: var(--green); font-weight: 700; }
.verdict .t { color: var(--tomato); font-weight: 700; }
table.ledger { width: 100%; border-collapse: collapse; font-size: 0.92rem; }
table.ledger th { font-family: var(--mono); font-size: 0.68rem; letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--ink-soft); font-weight: 400; text-align: right; padding: 0.5rem 0.6rem; border-bottom: 2px solid var(--ink); }
table.ledger th:first-child, table.ledger td:first-child { text-align: left; }
table.ledger td { font-family: var(--mono); text-align: right; padding: 0.6rem; border-bottom: 1px solid var(--rule); }
table.ledger td:first-child { font-family: inherit; }
table.ledger tr.ours td { background: var(--kraft); font-weight: 700; }
table.ledger td.bad { color: var(--tomato); }
.bars { margin-top: 1.4rem; }
.bars .row { display: grid; grid-template-columns: 15rem 1fr 5rem; gap: 0.8rem; align-items: center; padding: 0.3rem 0; font-size: 0.86rem; }
.bars .bar { height: 0.7rem; background: var(--tomato); opacity: 0.85; }
.bars .row.ours .bar { background: var(--green); opacity: 1; }
.bars .val { font-family: var(--mono); font-size: 0.8rem; text-align: right; }
.footnote { font-size: 0.82rem; color: var(--ink-soft); margin-top: 1rem; max-width: 70ch; }

@media (max-width: 640px) {
  .loadlist .head, .loadlist .line { grid-template-columns: 4rem 1fr; }
  .loadlist .range-cell { grid-column: 1 / -1; }
  .bars .row { grid-template-columns: 8rem 1fr 4rem; }
}
